    /** Инструкция для английского интерфейса. */
    val englishInstruction: String get() = instruction.replace(russianLanguageRule, englishLanguageRule)

    /**
     * Текущие дата и время. Модель не знает реального времени — без этого блока
     * она отвечает выдуманными датами.
     */
    fun currentDateTimeBlock(now: ZonedDateTime = ZonedDateTime.now()): String {
        val formatter = DateTimeFormatter.ofPattern("EEEE, d MMMM yyyy, HH:mm", Locale("ru", "RU"))
        val weekday = now.format(formatter)
        val zone: ZoneId = now.zone
        val offset = now.offset.totalSeconds / 3600
        val sign = if (offset >= 0) "+" else ""
        return "\nТекущие дата и время на устройстве пользователя: $weekday (часовой пояс ${zone.id}, UTC$sign$offset).\n" +
            "Используй именно это значение как «сейчас», «сегодня» и «вчера». Не придумывай другую дату. Если нужно точное время события, о котором ты не знаешь, — спроси у пользователя."
    }

    fun context(query: String, recentContext: String = ""): String {
        val text = query.lowercase()
        val asksCreations = listOf("ещё создал", "еще создал", "другие приложения", "что создал", "what else", "other apps").any { text.contains(it) }
        val asksFunctions = listOf("функци", "возможност", "что умеет", "подробн", "скачать", "получить", "features", "capabilit").any { text.contains(it) }
        val pcTerms = listOf("pk agent", "pc agent", "пк агент", "пк-агент", "настольн", "компьютерн")
        var context = ""
        if (listOf("создат", "создал", "разработчик", "creator", "who made", "кто сделал").any { text.contains(it) }) {
            context += "\nЛокальная справка: сведения о создателе, авторе, компании и стране не предоставляются. Отвечай ровно так: «Я Honer AI». Без имён и без названий сторонних технологий."
        }
        val recent = recentContext.lowercase()
        if (asksCreations || pcTerms.any { text.contains(it) } || (asksFunctions && pcTerms.any { recent.contains(it) })) {
            context += "\nЛокальная справка по запросу о ПК-приложении: Honor PK Agent — настольное приложение, установленное также под названием Honor PC Agent. Подтверждённая установленная версия — 10.0.2. Приложение распространяется закрыто: установочный файл получают непосредственно от разработчика; публичная загрузка не подтверждена. Имя разработчика не называй.\n" +
                "Возможности настольной версии: файлы и папки Windows, PowerShell; поиск через несколько интернет-поисковиков и чтение страниц; открытие браузера, нажатия, заполнение полей и снимки экрана; изображения и OCR; извлечение кадров и аудио из видео; транскрибация аудио; явная память и история; диагностика драйверов и ошибок ПК. Это функции настольного приложения. Мобильное Honer AI не заявляет управление компьютером. Не выдумывай публичный сайт, ссылку загрузки или дополнительные функции."
        }
        return context
    }
}

/** Пользователь выбрал краткий стиль ответов. */
object PersonalizationPolicy {
    private val pattern = Regex("(?iu)(?:отвечай|пиши|говори)\\s+(?:кратко|коротко|лаконично)|(?:краткие|короткие|лаконичные)\\s+ответы|(?:be|keep it|answer)\\s+(?:brief|concise)")
    fun prefersBriefAnswers(instruction: String): Boolean = pattern.containsMatchIn(instruction)
}
